pub static KNOWN_TYPES: OnceLock<HashSet<&'static str>> = OnceLock::new();
pub static PROPERTY_RANGES: OnceLock<HashMap<&'static str, &'static [&'static str]>> = OnceLock::new();

pub fn init_vocabulary() {
    KNOWN_TYPES.get_or_init(|| {
        KNOWN_TYPES_DATA.iter().copied().collect()
    });
    PROPERTY_RANGES.get_or_init(|| {
        let mut map = HashMap::new();
        for (k, v) in PROPERTY_RANGES_DATA {
            map.insert(*k, *v);
        }
        map
    });
}

pub struct SchemaVocabulary;

impl SchemaVocabulary {
    pub fn is_known_type(type_name: &str) -> bool {
        init_vocabulary();
        let clean = type_name.trim_start_matches("schema:").trim_start_matches("https://schema.org/");
        KNOWN_TYPES.get().map_or(false, |set| set.contains(clean))
    }

    pub fn get_property_ranges(prop_name: &str) -> Option<&'static [&'static str]> {
        init_vocabulary();
        let clean = prop_name.trim_start_matches("schema:").trim_start_matches("https://schema.org/");
        PROPERTY_RANGES.get().and_then(|map| map.get(clean).copied())
    }

    pub fn get_unambiguous_range_type(prop_name: &str) -> Option<&'static str> {
        if let Some(ranges) = Self::get_property_ranges(prop_name) {
            if ranges.len() == 1 {
                let target = ranges[0];
                if target != "Text" && target != "URL" && target != "Number" && target != "Boolean" && target != "Date" && target != "DateTime" {
                    return Some(target);
                }
            }
        }
        None
    }
}
